import os
import sqlite3
from datetime import datetime, timezone
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('lms-content')
DB = os.environ.get('LMS_DB_PATH', 'lms.db')

def _cols(t, b, d, p):
    c = {}
    if t is not None:
        t = t.strip()
        if not t:
            raise ValueError('title cannot be empty')
        c['title'] = t
    if b is not None:
        c['body_markdown'] = b
    if d is not None:
        if d < 0:
            raise ValueError('duration_minutes must be non-negative')
        c['duration_minutes'] = d
    if p is not None:
        c['is_published'] = 1 if p else 0
    return c

def _grant_student_access(cn, lesson_id):
    # When a lesson is published, give the student role view permission on it.
    cn.execute(
        "INSERT OR IGNORE INTO lesson_permissions (lesson_id, role, permission) VALUES (?, 'student', 'view')",
        (lesson_id,),
    )

@mcp.tool()
def update_lesson_details(lesson_id: int, title: str=None, body_markdown: str=None, duration_minutes: int=None, is_published: bool=None) -> dict:
    c = _cols(title, body_markdown, duration_minutes, is_published)
    if not c:
        return {'updated': False, 'error': 'No fields provided to update'}
    c['updated_at'] = datetime.now(timezone.utc).isoformat()
    s = ', '.join((f'{k} = ?' for k in c))
    v = list(c.values()) + [lesson_id]
    cn = sqlite3.connect(DB)
    try:
        cur = cn.execute(f'UPDATE lessons SET {s} WHERE id = ?', v)
        if is_published and cur.rowcount:
            _grant_student_access(cn, lesson_id)
        cn.commit()
        n = cur.rowcount
    finally:
        cn.close()
    if n == 0:
        return {'updated': False, 'error': f'Lesson {lesson_id} not found'}
    return {'updated': True, 'lesson_id': lesson_id, 'fields': sorted((k for k in c if k != 'updated_at'))}
